DECLARE n NUMBER; BEGIN SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_CONTINUITY_ARTIFACT_REVS'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_CONTINUITY_ARTIFACT_REVS (ARTIFACT_ID VARCHAR(128) NOT NULL REFERENCES CX_CONTINUITY_ARTIFACTS(ARTIFACT_ID), REVISION_ID VARCHAR(128) NOT NULL, REVISION_NO INTEGER NOT NULL CHECK(REVISION_NO>0), NATIVE_ENTITY_ID VARCHAR(128) NOT NULL UNIQUE, CONTENT_DIGEST VARCHAR(64) NOT NULL, CANDIDATE_ID VARCHAR(128) NOT NULL, CANDIDATE_REVISION_NO INTEGER NOT NULL, CREATED_BY VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, PRIMARY KEY(ARTIFACT_ID,REVISION_ID), UNIQUE(ARTIFACT_ID,REVISION_NO), UNIQUE(CANDIDATE_ID,CANDIDATE_REVISION_NO), FOREIGN KEY(CANDIDATE_ID,CANDIDATE_REVISION_NO) REFERENCES CX_CANDIDATE_REVISIONS(CANDIDATE_ID,REVISION_NO))'; END IF; END;
/

DECLARE n NUMBER; BEGIN SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_EXPERIENCE_META'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_EXPERIENCE_META (ENTITY_ID VARCHAR(128) PRIMARY KEY, PROBLEM CLOB NOT NULL, SOLUTION CLOB NOT NULL, VALIDATION CLOB NOT NULL, APPLICABILITY CLOB NOT NULL)'; END IF; END;
/

DECLARE n NUMBER; BEGIN SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_SKILL_CONTRACTS'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_SKILL_CONTRACTS (ENTITY_ID VARCHAR(128) PRIMARY KEY, INPUT_CONTRACT CLOB NOT NULL, OUTPUT_CONTRACT CLOB NOT NULL)'; END IF; END;
/

DECLARE n NUMBER; BEGIN SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_SKILL_REQUIRED_ACTIONS'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_SKILL_REQUIRED_ACTIONS (ENTITY_ID VARCHAR(128) NOT NULL REFERENCES CX_SKILL_CONTRACTS(ENTITY_ID), ITEM_NO INTEGER NOT NULL CHECK(ITEM_NO>0), RESOURCE_ACTION VARCHAR(128) NOT NULL, PRIMARY KEY(ENTITY_ID,ITEM_NO))'; END IF; END;
/

DECLARE n NUMBER; BEGIN SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_CONTEXT_PUBLICATIONS'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_CONTEXT_PUBLICATIONS (PUBLICATION_ID VARCHAR(128) PRIMARY KEY, FAMILY VARCHAR(24) NOT NULL CHECK(FAMILY IN (''MEMORY'',''KNOWLEDGE'',''EXPERIENCE'',''SKILL'',''HANDOFF'')), ENTITY_ID VARCHAR(128) NOT NULL, SOURCE_REVISION_ID VARCHAR(128) NOT NULL, CONTENT_DIGEST VARCHAR(64) NOT NULL, SOURCE_SECURITY_DOMAIN_ID VARCHAR(128) NOT NULL REFERENCES CX_SECURITY_DOMAINS(SECURITY_DOMAIN_ID), TARGET_SECURITY_DOMAIN_ID VARCHAR(128) NOT NULL REFERENCES CX_SECURITY_DOMAINS(SECURITY_DOMAIN_ID), PUBLISHED_BY VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), PURPOSE VARCHAR(1000) NOT NULL, CLASSIFICATION VARCHAR(24) NOT NULL CHECK(CLASSIFICATION IN (''PUBLIC'',''INTERNAL'',''CONFIDENTIAL'',''RESTRICTED'')), EXPIRES_AT TIMESTAMP NOT NULL, STATUS VARCHAR(24) NOT NULL CHECK(STATUS IN (''PUBLISHED'',''REVOKED'')), VERSION INTEGER NOT NULL CHECK(VERSION>0), IDEMPOTENCY_KEY VARCHAR(128) NOT NULL, REQUEST_DIGEST VARCHAR(64) NOT NULL, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, UNIQUE(PUBLISHED_BY,IDEMPOTENCY_KEY))'; END IF; END;
/

DECLARE n NUMBER; BEGIN SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_PUBLICATION_EVENTS'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_PUBLICATION_EVENTS (EVENT_ID VARCHAR(128) PRIMARY KEY, PUBLICATION_ID VARCHAR(128) NOT NULL REFERENCES CX_CONTEXT_PUBLICATIONS(PUBLICATION_ID), VERSION INTEGER NOT NULL CHECK(VERSION>0), ACTOR_ID VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), OPERATION VARCHAR(24) NOT NULL CHECK(OPERATION IN (''PUBLISH'',''REVOKE'')), REASON VARCHAR(1000) NOT NULL, IDEMPOTENCY_KEY VARCHAR(128) NOT NULL, REQUEST_DIGEST VARCHAR(64) NOT NULL, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, UNIQUE(PUBLICATION_ID,VERSION), UNIQUE(ACTOR_ID,OPERATION,IDEMPOTENCY_KEY))'; END IF; END;
/

DECLARE n NUMBER; BEGIN SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_DIAGNOSTIC_RUNS'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_DIAGNOSTIC_RUNS (RUN_ID VARCHAR(128) PRIMARY KEY, REQUEST_ID VARCHAR(128) NOT NULL, PRINCIPAL_ID VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), SECURITY_DOMAIN_ID VARCHAR(128) NOT NULL REFERENCES CX_SECURITY_DOMAINS(SECURITY_DOMAIN_ID), STATUS VARCHAR(24) NOT NULL CHECK(STATUS IN (''PASS'',''FAIL'',''UNAVAILABLE'',''UNOBSERVED'')), CHECK_COUNT INTEGER NOT NULL CHECK(CHECK_COUNT>0), PURPOSE VARCHAR(1000) NOT NULL, IDEMPOTENCY_KEY VARCHAR(128) NOT NULL, REQUEST_DIGEST VARCHAR(64) NOT NULL, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, UNIQUE(PRINCIPAL_ID,IDEMPOTENCY_KEY))'; END IF; END;
/

DECLARE n NUMBER; BEGIN SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_DIAGNOSTIC_CHECKS'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_DIAGNOSTIC_CHECKS (RUN_ID VARCHAR(128) NOT NULL REFERENCES CX_DIAGNOSTIC_RUNS(RUN_ID), ITEM_NO INTEGER NOT NULL CHECK(ITEM_NO>0), CHECK_CODE VARCHAR(64) NOT NULL, STATUS VARCHAR(24) NOT NULL CHECK(STATUS IN (''PASS'',''FAIL'',''UNAVAILABLE'',''UNOBSERVED'')), OBSERVED CHAR(1) NOT NULL CHECK(OBSERVED IN (''Y'',''N'')), DETAIL_CODE VARCHAR(128) NOT NULL, PRIMARY KEY(RUN_ID,ITEM_NO), UNIQUE(RUN_ID,CHECK_CODE), CHECK((STATUS IN (''PASS'',''FAIL'') AND OBSERVED=''Y'') OR (STATUS=''UNOBSERVED'' AND OBSERVED=''N'') OR STATUS=''UNAVAILABLE''))'; END IF; END;
/

DECLARE n NUMBER; BEGIN SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_ARTIFACT_RETIREMENTS'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_ARTIFACT_RETIREMENTS (RETIREMENT_ID VARCHAR(128) PRIMARY KEY, FAMILY VARCHAR(24) NOT NULL CHECK(FAMILY IN (''MEMORY'',''KNOWLEDGE'',''EXPERIENCE'',''SKILL'')), ENTITY_ID VARCHAR(128) NOT NULL, SOURCE_REVISION_ID VARCHAR(128) NOT NULL, CONTENT_DIGEST VARCHAR(64) NOT NULL, VERSION INTEGER NOT NULL CHECK(VERSION>0), ACTOR_ID VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), SECURITY_DOMAIN_ID VARCHAR(128) NOT NULL REFERENCES CX_SECURITY_DOMAINS(SECURITY_DOMAIN_ID), REASON VARCHAR(1000) NOT NULL, IDEMPOTENCY_KEY VARCHAR(128) NOT NULL, REQUEST_DIGEST VARCHAR(64) NOT NULL, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, UNIQUE(FAMILY,ENTITY_ID), UNIQUE(ACTOR_ID,IDEMPOTENCY_KEY))'; END IF; END;
/

